<div class="titulo-pagina"><div><p class="sobretitulo">Contato</p><h1><?= $familiar ? 'Editar familiar' : 'Cadastrar familiar' ?></h1></div><a href="?route=familiares">Voltar</a></div>
<section class="cartao"><form class="formulario formulario-largo" method="post" action="?route=<?= $familiar?'familiares-atualizar&amp;id='.AsiloView::escape($familiar['id']):'familiares-criar' ?>"><input type="hidden" name="csrf_token" value="<?=AsiloView::escape($csrfToken)?>"><label>Nome<input name="nome" required maxlength="120" value="<?=AsiloView::escape($familiar['nome']??'')?>"></label><label>CPF<input name="cpf" maxlength="14" value="<?=AsiloView::escape($familiar['cpf']??'')?>"></label><label>Telefone<input name="telefone" required maxlength="30" value="<?=AsiloView::escape($familiar['telefone']??'')?>"></label><label>E-mail<input type="email" name="email" maxlength="160" value="<?=AsiloView::escape($familiar['email']??'')?>"></label><label>Parentesco principal<input name="parentesco_principal" maxlength="60" value="<?=AsiloView::escape($familiar['parentesco_principal']??'')?>"></label><label>Conta de acesso ao portal<select name="usuario_id"><option value="">Contato sem conta</option><?php $contaAtualEncontrada = false; foreach ($contas as $conta): $selecionada = (string)($familiar['usuario_id'] ?? '') === (string)$conta['id']; $contaAtualEncontrada = $contaAtualEncontrada || $selecionada; ?><option value="<?=AsiloView::escape($conta['id'])?>" <?=$selecionada?'selected':''?>><?=AsiloView::escape($conta['nome'].' — '.$conta['email'])?></option><?php endforeach; if (!empty($familiar['usuario_id']) && !$contaAtualEncontrada): ?><option value="<?=AsiloView::escape($familiar['usuario_id'])?>" selected>Associação atual (conta indisponível para acesso)</option><?php endif; ?></select></label><p class="texto-suave">Selecione uma conta ativa de perfil Familiar. A opção “Contato sem conta” remove o acesso deste contato ao portal.</p><button>Salvar familiar</button></form></section>
